/**
 * PresentValueTab.jsx
 * Present Value Calculator
 */

import React, { useState } from 'react';
import { DollarSign } from 'lucide-react';

const PresentValueTab = () => {
  const [futureValue, setFutureValue] = useState('');
  const [rate, setRate] = useState('');
  const [periods, setPeriods] = useState('');
  const [result, setResult] = useState(null);

  const calculatePresentValue = () => {
    const fv = parseFloat(futureValue);
    const r = parseFloat(rate) / 100;
    const n = parseFloat(periods);

    if (fv && r && n) {
      const pv = fv / Math.pow((1 + r), n);

      setResult({
        presentValue: pv.toFixed(2),
        discount: (fv - pv).toFixed(2)
      });
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-3 mb-6">
        <DollarSign className="w-6 h-6 text-red-600" />
        <h2 className="text-2xl font-semibold">Present Value Calculator</h2>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium mb-2">Future Value ($)</label>
            <input
              type="number"
              value={futureValue}
              onChange={(e) => setFutureValue(e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800"
              placeholder="10000"
            />
          </div>

          <div>
            <label className="block text-sm font-medium mb-2">Discount Rate (%)</label>
            <input
              type="number"
              value={rate}
              onChange={(e) => setRate(e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800"
              placeholder="5"
              step="0.01"
            />
          </div>

          <div>
            <label className="block text-sm font-medium mb-2">Number of Periods</label>
            <input
              type="number"
              value={periods}
              onChange={(e) => setPeriods(e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800"
              placeholder="10"
            />
          </div>

          <button
            onClick={calculatePresentValue}
            className="w-full bg-red-600 hover:bg-red-700 text-white py-2 px-4 rounded-lg transition-colors"
          >
            Calculate
          </button>
        </div>

        {result && (
          <div className="bg-gray-50 dark:bg-gray-800 p-6 rounded-lg">
            <h3 className="text-lg font-semibold mb-4">Results</h3>
            <div className="space-y-2">
              <p><span className="font-medium">Present Value:</span> ${result.presentValue}</p>
              <p><span className="font-medium">Discount Amount:</span> ${result.discount}</p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default PresentValueTab;
